package generated;

import com.openjiuwen.core.foundation.tool.Tool;
import com.openjiuwen.core.foundation.tool.ToolCard;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class WealthQueryTool extends Tool {
  private static final String BALANCE_OPERATION = "get_account_balance";
  private static final String PRODUCTS_OPERATION = "list_wealth_products";
  private static final String INPUT_ERROR = "TOOL_INPUT_CONTRACT_INVALID";
  private static final String RESPONSE_ERROR = "TOOL_RESPONSE_CONTRACT_INVALID";
  private static final String CARD_ERROR = "TOOL_CARD_CONTRACT_INVALID";

  private final Tool transport;
  private final String cardName;

  public WealthQueryTool(Tool transport) {
    super(cardOf(transport));
    this.transport = transport;
    this.cardName = cardOf(transport).getName();
    if (!BALANCE_OPERATION.equals(cardName) && !PRODUCTS_OPERATION.equals(cardName)) {
      throw new IllegalArgumentException(CARD_ERROR);
    }
  }

  private static ToolCard cardOf(Tool transport) {
    if (transport == null) {
      throw new IllegalArgumentException(CARD_ERROR);
    }
    ToolCard card = transport.getCard();
    if (card == null) {
      throw new IllegalArgumentException(CARD_ERROR);
    }
    return card;
  }

  @Override
  protected Object invokeInternal(Map<String, Object> inputs, Map<String, Object> kwargs) throws Exception {
    if (BALANCE_OPERATION.equals(cardName)) {
      requireBalanceInput(inputs);
      return balanceResponse(transport.invoke(inputs, kwargs));
    }
    if (PRODUCTS_OPERATION.equals(cardName)) {
      requireProductsInput(inputs);
      return productsResponse(transport.invoke(inputs, kwargs));
    }
    throw new IllegalArgumentException(CARD_ERROR);
  }

  private static void requireBalanceInput(Map<String, Object> inputs) {
    if (inputs == null || inputs.size() != 1 || !inputs.containsKey("accountId")) {
      throw new IllegalArgumentException(INPUT_ERROR);
    }
    Object accountId = inputs.get("accountId");
    if (!(accountId instanceof String) || ((String) accountId).trim().isEmpty()) {
      throw new IllegalArgumentException(INPUT_ERROR);
    }
  }

  private static void requireProductsInput(Map<String, Object> inputs) {
    if (inputs == null || !inputs.isEmpty()) {
      throw new IllegalArgumentException(INPUT_ERROR);
    }
  }

  private static Map<String, Object> balanceResponse(Object response) {
    if (!(response instanceof Map)) {
      throw new IllegalStateException(RESPONSE_ERROR);
    }
    Map<?, ?> source = (Map<?, ?>) response;
    Object accountId = source.get("accountId");
    Object currency = source.get("currency");
    Object availableBalanceFen = source.get("availableBalanceFen");
    Object asOf = source.get("asOf");
    if (!(accountId instanceof String)
        || !(currency instanceof String)
        || !isInteger(availableBalanceFen)
        || !(asOf instanceof String)) {
      throw new IllegalStateException(RESPONSE_ERROR);
    }
    Map<String, Object> result = new LinkedHashMap<String, Object>();
    result.put("accountId", accountId);
    result.put("currency", currency);
    result.put("availableBalanceFen", availableBalanceFen);
    result.put("asOf", asOf);
    return result;
  }

  private static Map<String, Object> productsResponse(Object response) {
    if (!(response instanceof Map)) {
      throw new IllegalStateException(RESPONSE_ERROR);
    }
    Map<?, ?> source = (Map<?, ?>) response;
    Object items = source.get("items");
    Object version = source.get("version");
    if (!(items instanceof List) || !(version instanceof String)) {
      throw new IllegalStateException(RESPONSE_ERROR);
    }
    List<Object> projectedItems = new ArrayList<Object>();
    for (Object rawItem : (List<?>) items) {
      if (!(rawItem instanceof Map)) {
        throw new IllegalStateException(RESPONSE_ERROR);
      }
      Map<?, ?> item = (Map<?, ?>) rawItem;
      Object productId = item.get("productId");
      Object name = item.get("name");
      Object status = item.get("status");
      Object minimumAmountFen = item.get("minimumAmountFen");
      Object description = item.get("description");
      if (!(productId instanceof String)
          || !(name instanceof String)
          || !(status instanceof String)
          || !isInteger(minimumAmountFen)
          || !(description instanceof String)) {
        throw new IllegalStateException(RESPONSE_ERROR);
      }
      Map<String, Object> projectedItem = new LinkedHashMap<String, Object>();
      projectedItem.put("productId", productId);
      projectedItem.put("name", name);
      projectedItem.put("status", status);
      projectedItem.put("minimumAmountFen", minimumAmountFen);
      projectedItem.put("description", description);
      projectedItems.add(projectedItem);
    }
    Map<String, Object> result = new LinkedHashMap<String, Object>();
    result.put("items", projectedItems);
    result.put("version", version);
    return result;
  }

  private static boolean isInteger(Object value) {
    return value instanceof Integer || value instanceof Long;
  }
}
